head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > P > selectedRowColor]<br/>현재 포커스된 Row 의 배경색으로 적용될 색상을 설정합니다. focusMode='row','both' 인 경우에 동작합니다.",
    "validation" : [
        "focusFooter=true 인 경우 Footer 영역의 포커스된 Row 에도 selectedRowColor 가 적용됩니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 조건 설정 (con_ 옵션을 properties 객체로 모아 createCList 로 속성 문자열 생성, 빈값 자동 제외)
    //  - selectedRowColor 는 색상이름/코드/rgb/rgba 다양한 형식의 정적 select 값(미설정 포함)
    //  - focusMode 는 row 고정 (selectedRowColor 가 동작하는 모드)
    //  - focusFooter 는 true 고정 (Footer 영역 포커스 기능 활성화 → Footer 영역 포커스된 Row 에도 selectedRowColor 적용)
    let properties = {
        selectedRowColor : con_selectedRowColor.getValue(),
        focusMode        : "row",
        focusFooter      : "true"
    };
    let cList = $c.gcm.createCList(properties);

    // 이벤트 바인딩 (Footer Cell 클릭 시 onfooterclick 발생 → 포커스된 Footer Row 의 셀들 배경색 자동 출력)
    let eList = $c.gcm.createEList(["onfooterclick"]);

    let grp_comp = $c.gcm.getTestGroup();
    let strNameSpace = $c.gcm.getNameSpace();

    // 현재 설정 상태 라벨 (target 생성 전 가장 먼저 생성)
    let lblRow = (properties.selectedRowColor === '') ? '미설정' : properties.selectedRowColor;
    $c.gcm.createLabel('label="selectedRowColor=' + lblRow + ' / focusMode=row / focusFooter=true 로 GridView 생성 (Footer 영역 ft1~ft4 포함). Footer 의 셀을 클릭하면 포커스된 Footer Row 의 셀들 배경색 출력"', '', 'label1');

    // dataList 생성 (column id 를 col1~col4 로 맞춤)
    $c.gcm.createDynamicDataList('', '', 'dlt_bind');

    // target 생성 (Footer 영역 포함 그리드 직접 구성)
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' ' + cList + ' ' + eList + ' dataList="data:dlt_bind" checkAllType="false" id="" style="width:420px;height:280px;">';
    strTarget += '<w2:caption style="" id="caption1" value="selectedRowColor (Footer) 테스트 그리드"></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="100" style="" inputType="text" id="column1" value="name1"></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="column2" value="name2"></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="column3" value="name3"></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="column4" value="name4"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="100" style="" inputType="text" id="col1" value=""></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="col2" value=""></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="col3" value=""></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="col4" value=""></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '<w2:footer style="" id="footer1">';
    strTarget += '<w2:row style="" id="row3">';
    strTarget += '<w2:column width="100" style="" inputType="text" id="ft1" value="footer1"></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="ft2" value="footer2"></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="ft3" value="footer3"></w2:column>';
    strTarget += '<w2:column width="100" style="" inputType="text" id="ft4" value="footer4"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:footer>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );
}



// onfooterclick : Footer Cell 을 클릭할 때 발생 (footerId : 클릭된 Footer Cell ID)
//  - @spec : focusFooter=true 이면 onfooterclick 발생 전 Footer Cell 포커스가 적용되므로
//            핸들러 안에서 getFocusedFooterCell() 로 포커스된 Footer Cell 을 조회 가능
//  - focusMode=row 이므로 Footer Cell 클릭 시 클릭된 Cell 이 속한 Footer Row 전체가 포커스됨
//    → 포커스된 Footer Cell(getFocusedFooterCell().td)이 속한 같은 Footer Row 의 셀들 배경색을 읽어
//      selectedRowColor 가 Footer 영역의 포커스된 Row 에도 적용되는지 자동 출력
scwin.target1_onfooterclick = function (footerId) {
    // 출력 누적 방지 clear
    wf_body_bottom.getObj("scwin").btn_clear_onclick();
    wf_body_bottom.getObj("scwin").setReturnValue("=====target1_onfooterclick=====");
    wf_body_bottom.getObj("scwin").setReturnValue("클릭된 footerId : " + footerId);

    let lblRow = (con_selectedRowColor.getValue() === '') ? '미설정' : con_selectedRowColor.getValue();
    wf_body_bottom.getObj("scwin").setReturnValue("[selectedRowColor] " + lblRow);

    // focusFooter=true 시 이벤트 시점에 이미 포커스된 Footer Cell 조회
    let rtn = target1.getFocusedFooterCell();

    if (!rtn || rtn.length === 0) {
        wf_body_bottom.getObj("scwin").setReturnValue("[포커스된 Footer Row] 없음");
        return;
    }

    // 포커스된 Footer Cell 의 td 가 속한 tr(같은 Footer Row) 의 모든 셀(td) 배경색을 읽어 출력
    //  - focusMode=row 이므로 selectedRowColor 는 포커스된 Footer Row 의 셀들 전체에 적용됨
    let baseTd = rtn[0].td;
    let tr = baseTd ? baseTd.parentNode : null;

    if (!tr) {
        wf_body_bottom.getObj("scwin").setReturnValue("[포커스된 Footer Row] td 없음");
        return;
    }

    let tds = tr.querySelectorAll("td");
    let result = '';
    for (let i = 0; i < tds.length; i++) {
        let bgColor = window.getComputedStyle(tds[i]).backgroundColor;
        result += "td(" + i + ")=" + bgColor;
        if (i < tds.length - 1) {
            result += " / ";
        }
    }
    wf_body_bottom.getObj("scwin").setReturnValue("[포커스 Footer Row(rowIndex=" + rtn[0].rowIndex + ") 셀 배경색] " + result);
}
